:root {
  color-scheme: light;
  --canvas: var(--rhoe-canvas, #eef1ed);
  --surface: var(--rhoe-surface, #fcfdfb);
  --surface-muted: var(--rhoe-surface-muted, #e2e6e1);
  --text: var(--rhoe-text, #191b19);
  --text-secondary: var(--rhoe-text-secondary, #59605b);
  --border: var(--rhoe-border, #d9ddd9);
  --primary: var(--rhoe-primary, #252725);
  --primary-hover: var(--rhoe-primary-hover, #343734);
  --primary-foreground: var(--rhoe-primary-foreground, #f8faf8);
  --success: var(--rhoe-success, #18794e);
  --success-foreground: var(--rhoe-success-foreground, #ffffff);
  --success-surface: var(--rhoe-success-surface, #e7f6ec);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #17653f);
  --warning: var(--rhoe-warning, #946200);
  --warning-foreground: var(--rhoe-warning-foreground, #ffffff);
  --warning-surface: var(--rhoe-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #6b4600);
  --danger: var(--rhoe-danger, #b42318);
  --danger-foreground: var(--rhoe-danger-foreground, #ffffff);
  --danger-surface: var(--rhoe-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #8f1d14);
  --focus: var(--rhoe-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --duration-considered: 480ms;
  --duration-reveal: 600ms;
  --duration-expand: 720ms;
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --input-expanded-duration: var(--duration-considered);
  --input-expanded-ease: var(--ease-enter);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--rhoe-canvas, #121412);
    --surface: var(--rhoe-surface, #1a1d1a);
    --surface-muted: var(--rhoe-surface-muted, #232623);
    --text: var(--rhoe-text, #f1f3f0);
    --text-secondary: var(--rhoe-text-secondary, #afb5b0);
    --border: var(--rhoe-border, #373b37);
    --primary: var(--rhoe-primary, #ecefeb);
    --primary-hover: var(--rhoe-primary-hover, #ffffff);
    --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
    --success: var(--rhoe-success, #62c98f);
    --success-foreground: var(--rhoe-success-foreground, #092416);
    --success-surface: var(--rhoe-success-surface, #173526);
    --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
    --warning: var(--rhoe-warning, #e9ad45);
    --warning-foreground: var(--rhoe-warning-foreground, #291900);
    --warning-surface: var(--rhoe-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
    --danger: var(--rhoe-danger, #ff716b);
    --danger-foreground: var(--rhoe-danger-foreground, #260503);
    --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
    --focus: var(--rhoe-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--rhoe-canvas, #121412);
  --surface: var(--rhoe-surface, #1a1d1a);
  --surface-muted: var(--rhoe-surface-muted, #232623);
  --text: var(--rhoe-text, #f1f3f0);
  --text-secondary: var(--rhoe-text-secondary, #afb5b0);
  --border: var(--rhoe-border, #373b37);
  --primary: var(--rhoe-primary, #ecefeb);
  --primary-hover: var(--rhoe-primary-hover, #ffffff);
  --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
  --success: var(--rhoe-success, #62c98f);
  --success-foreground: var(--rhoe-success-foreground, #092416);
  --success-surface: var(--rhoe-success-surface, #173526);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
  --warning: var(--rhoe-warning, #e9ad45);
  --warning-foreground: var(--rhoe-warning-foreground, #291900);
  --warning-surface: var(--rhoe-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
  --danger: var(--rhoe-danger, #ff716b);
  --danger-foreground: var(--rhoe-danger-foreground, #260503);
  --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
  --focus: var(--rhoe-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .rhoe-code-source .shiki,
html[data-theme="dark"] .rhoe-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .rhoe-code-source .shiki,
  html:not([data-theme="light"]) .rhoe-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes rhoe-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes rhoe-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes rhoe-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

@keyframes rhoe-calendar-range-reveal {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}

export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    expand: 0.72,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import {
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { ChevronDown } from "lucide-react";
import {
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
  type HTMLMotionProps,
  type Transition,
} from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export interface ExpandableCardProps
  extends Omit<HTMLMotionProps<"article">, "children" | "title"> {
  title: ReactNode;
  description?: ReactNode;
  children: ReactNode;
  width?: number;
  expandedWidth?: number;
  defaultExpanded?: boolean;
}

const still: Transition = { duration: 0 };

export function ExpandableCard({
  title,
  description,
  children,
  width,
  expandedWidth = width,
  defaultExpanded = false,
  className,
  style,
  onKeyDown,
  ...props
}: ExpandableCardProps) {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const [availableWidth, setAvailableWidth] = useState<number>();
  const trackRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelId = useId();
  const reduceMotion = useReducedMotion() ?? false;
  const cardWidth = useMotionValue<number | string>("100%");
  const firstMeasurement = useRef(true);

  useLayoutEffect(() => {
    const track = trackRef.current;
    if (!track) return;
    const measure = () => setAvailableWidth(track.clientWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(track);
    return () => observer.disconnect();
  }, []);

  const cap = expanded ? expandedWidth : width;
  const measuredWidth = availableWidth
    ? Math.min(availableWidth, cap ?? availableWidth)
    : undefined;
  const contentWidth = availableWidth
    ? Math.min(availableWidth, expandedWidth ?? availableWidth)
    : undefined;

  useLayoutEffect(() => {
    if (measuredWidth === undefined) return;
    if (firstMeasurement.current) {
      firstMeasurement.current = false;
      cardWidth.jump(measuredWidth);
      return;
    }
    const controls = animate(cardWidth, measuredWidth, {
      ...(reduceMotion ? still : motionTokens.spring.smooth),
      delay: expanded ? 0 : 0.06,
    });
    return () => controls.stop();
  }, [cardWidth, expanded, measuredWidth, reduceMotion]);

  const caps = {
    "--card-width": width ? `${width}px` : undefined,
    "--card-expanded-width": expandedWidth ? `${expandedWidth}px` : undefined,
  } as CSSProperties;

  return (
    <div ref={trackRef} className="flex w-full min-w-0 justify-center">
      <motion.article
        {...props}
        className={["w-full max-w-[var(--card-width,100%)] overflow-hidden rounded-[var(--radius-surface)] border border-[var(--border)] bg-[var(--surface)] text-[var(--text)] shadow-[var(--shadow-resting)] data-[expanded=true]:max-w-[var(--card-expanded-width,var(--card-width,100%))] data-[measured]:max-w-full", className].filter(Boolean).join(" ")}
        data-expanded={expanded}
        data-measured={availableWidth === undefined ? undefined : ""}
        style={{ ...style, ...caps, width: cardWidth }}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          if (event.defaultPrevented || event.key !== "Escape" || !expanded) return;
          event.preventDefault();
          setExpanded(false);
          triggerRef.current?.focus();
        }}
      >
        <button
          ref={triggerRef}
          type="button"
          className="flex min-h-[68px] w-full items-center justify-between gap-5 border-0 bg-transparent px-5 py-4 text-left text-[inherit] transition-colors duration-[var(--duration-fast)] ease-[var(--ease-standard)] [webkit-tap-highlight-color:transparent] hover:bg-[var(--surface-muted)] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-[-3px] motion-reduce:transition-none"
          aria-expanded={expanded}
          aria-controls={panelId}
          onClick={() => setExpanded((current) => !current)}
        >
          <span className="min-w-0">
            <strong className="block text-sm font-[620] tracking-[-0.01em]">{title}</strong>
            {description && <span className="mt-1 block text-xs leading-[1.5] text-[var(--text-secondary)]">{description}</span>}
          </span>
          <motion.span
            className="inline-flex shrink-0 text-[var(--text-secondary)]"
            aria-hidden="true"
            initial={false}
            animate={{ rotate: expanded ? 180 : 0 }}
            transition={reduceMotion ? still : motionTokens.spring.smooth}
          >
            <ChevronDown size={18} />
          </motion.span>
        </button>

        <motion.div
          id={panelId}
          className="overflow-hidden bg-[var(--surface-muted)] shadow-[inset_0_1px_0_var(--border)]"
          {...(!expanded ? { inert: true } : {})}
          initial={false}
          animate={{ height: expanded ? "auto" : 0 }}
          transition={reduceMotion ? still : { ...motionTokens.spring.smooth, delay: expanded ? 0 : 0.06 }}
        >
          <motion.div
            className="max-w-none px-5 pt-[18px] pb-5 text-sm leading-[1.65] text-[var(--text-secondary)]"
            style={contentWidth ? { width: contentWidth - 2 } : undefined}
            initial={false}
            animate={{ opacity: expanded ? 1 : 0 }}
            transition={
              reduceMotion
                ? still
                : expanded
                  ? { duration: motionTokens.duration.standard, ease: motionTokens.ease.standard, delay: 0.12 }
                  : { duration: 0.1, ease: motionTokens.ease.standard }
            }
          >
            {children}
          </motion.div>
        </motion.div>
      </motion.article>
    </div>
  );
}
